+import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest'
+import { signPayload, notifyWebhook } from '../webhookNotifier.js'
+
+describe('webhookNotifier', () => {
+  it('signPayload produces sha256= hex', () => {
+    const secret = 'aabbcc'
+    const body = JSON.stringify({ x: 1 })
+    const sig = signPayload(secret, body)
+    expect(sig.startsWith('sha256=')).toBe(true)
+    expect(sig.length).toBeGreaterThan('sha256='.length)
+  })
+
+  it('retries on network errors and succeeds', async () => {
+    vi.useFakeTimers()
+    const fetchMock = vi.spyOn(global as any, 'fetch')
+    // first two calls: throw network error, third returns 200
+    fetchMock
+      .mockRejectedValueOnce(new Error('network'))
+      .mockRejectedValueOnce(new Error('network2'))
+      .mockResolvedValueOnce({ ok: true, status: 200 })
+
+    const cfg = { url: 'https://example.com/webhook', secret: 's' }
+    const payload = { event: 'task.completed' }
+
+    const p = notifyWebhook(cfg as any, payload as any, 'task.completed')
+
+    // advance timers for 1s (first retry)
+    await vi.runAllTimersAsync()
+    await p
+
+    expect(fetchMock).toHaveBeenCalledTimes(3)
+
+    fetchMock.mockRestore()
+    vi.useRealTimers()
+  })
+
+  it('stops retrying on 4xx', async () => {
+    const fetchMock = vi.spyOn(global as any, 'fetch')
+    fetchMock.mockResolvedValueOnce({ ok: false, status: 400 })
+
+    const cfg = { url: 'https://example.com/webhook', secret: 's' }
+    const payload = { event: 'task.completed' }
+
+    await notifyWebhook(cfg as any, payload as any, 'task.completed')
+    expect(fetchMock).toHaveBeenCalledTimes(1)
+    fetchMock.mockRestore()
+  })
+})
