@@ -0,0 +1,48 @@
+import crypto from 'crypto'
+
+export type WebhookConfig = { url: string; secret: string }
+
+export function signPayload(secret: string, body: string): string {
+  const h = crypto.createHmac('sha256', secret).update(body, 'utf8').digest('hex')
+  return `sha256=${h}`
+}
+
+export async function notifyWebhook(config: WebhookConfig, payload: Record<string, unknown>, event: 'task.completed' | 'task.failed'): Promise<void> {
+  const body = JSON.stringify(payload)
+  const signature = signPayload(config.secret, body)
+
+  const headers = {
+    'Content-Type': 'application/json',
+    'X-Pullwright-Event': event,
+    'X-Pullwright-Signature': signature,
+  }
+
+  const maxAttempts = 3
+  const delays = [1000, 2000, 4000]
+
+  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
+    try {
+      const res = await fetch(config.url, { method: 'POST', headers, body })
+      if (res.ok) return
+      const status = res.status
+      if (status >= 500 && status < 600) {
+        // retryable
+        const delay = delays[attempt - 1] ?? 4000
+        console.warn(`Webhook POST failed with ${status}, retrying in ${delay}ms (attempt ${attempt})`)
+        await new Promise((r) => setTimeout(r, delay))
+        continue
+      }
+      // non-retryable failure
+      console.error(`Webhook POST failed with status ${status}, not retrying`)
+      return
+    } catch (err: any) {
+      const delay = delays[attempt - 1] ?? 4000
+      console.warn(`Webhook POST network error: ${err?.message ?? err}. Retrying in ${delay}ms (attempt ${attempt})`)
+      if (attempt === maxAttempts) {
+        console.error(`Webhook POST failed after ${maxAttempts} attempts:`, err)
+        return
+      }
+      await new Promise((r) => setTimeout(r, delay))
+    }
+  }
+}
