+export async function saveWebhook(url: string): Promise<{ url: string; secret: string } | null> {
+  const res = await fetch(`${BASE}/api/settings/webhook`, {
+    method: 'PUT',
+    credentials: CREDENTIALS,
+    headers: { ...AUTH_HEADERS, 'Content-Type': 'application/json' },
+    body: JSON.stringify({ url }),
